#!/usr/bin/env python3
"""Build the shipment summary described in /app/docs/summary-format.md."""
import gzip
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal, ROUND_HALF_UP
from fractions import Fraction

KG = {"kg": Fraction(1), "g": Fraction(1, 1000), "lb": Fraction(45359237, 10**8),
      "oz": Fraction(28349523125, 10**12)}
HANDOVER_ORDER = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]
COUNTED = {"delivered", "delivered_late"}
MONTHS = {m: i + 1 for i, m in enumerate(
    "jan feb mar apr may jun jul aug sep oct nov dec".split())}

COLUMNS = {
    "east": {"id", "type", "shipped", "gross", "net", "status", "note"},
    "harbor": {"rec", "ref", "date", "weight", "state"},
    "lakeside": {"id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"},
    "river": {"t", "ref", "shipped", "weight", "status"},
    "west": {"id", "typ", "shipped", "weight", "status", "note"},
}
DELIM = {"east": ",", "lakeside": ",", "harbor": "|", "river": "\t", "west": ";"}
BASE_DATE = {"east": "YMD", "harbor": "iso", "lakeside": "iso", "river": "MM/DD/YYYY",
             "west": "DD.MM.YYYY"}
BASE_UNIT = {"east": "kg", "harbor": "kg", "lakeside": "kg", "river": "kg", "west": "kg",
             "central": "kg"}
WEIGHT_COL = {"east": "gross", "harbor": "weight", "lakeside": "gross_kg",
              "river": "weight", "west": "weight"}
ID_COL = {"east": "id", "harbor": "ref", "lakeside": "id", "river": "ref", "west": "id"}
TYPE_COL = {"east": "type", "harbor": "rec", "lakeside": "kind", "river": "t", "west": "typ"}
DATE_COL = {"east": "shipped", "harbor": "date", "lakeside": "shipped", "river": "shipped",
            "west": "shipped"}
STATUS_COL = {"east": "status", "harbor": "state", "lakeside": "status", "river": "status",
              "west": "status"}
HARBOR_STATES = {"DLV": "delivered", "DLL": "delivered_late", "CAN": "cancelled",
                 "RET": "returned", "HLD": "held"}
FW_CODES = {"D": "delivered", "L": "delivered_late", "C": "cancelled", "R": "returned",
            "H": "held"}


def read_bytes(path):
    with open(path, "rb") as f:
        b = f.read()
    if b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    return b


def decode(b):
    if b[:3] == b"\xef\xbb\xbf":
        return b[3:].decode("utf-8", "replace")
    if b[:2] in (b"\xff\xfe", b"\xfe\xff"):
        return b.decode("utf-16", "replace")
    head = b[:2048].decode("latin-1")
    m = re.search(r"^#\s*charset:\s*([\w.\-]+)", head, re.M | re.I)
    if m:
        try:
            return b.decode(m.group(1), "replace")
        except LookupError:
            pass
    try:
        return b.decode("utf-8")
    except UnicodeDecodeError:
        return b.decode("cp1252", "replace")


def norm_type(t):
    t = (t or "").strip().lower()
    if t in ("c", "cor", "corr", "correction", "amend"):
        return "correction"
    if t in ("v", "void"):
        return "void"
    return "new"


def norm_status(s):
    return re.sub(r"[\s\-]+", "_", (s or "").strip().lower())


def id_num(s):
    m = re.search(r"\d+", s or "")
    return int(m.group()) if m and re.match(r"\s*SH", s or "", re.I) else None


def parse_num(s, decimal_comma):
    s = s.strip().replace(" ", "")
    if decimal_comma:
        s = s.replace(".", "").replace(",", ".")
    else:
        s = s.replace(",", "")
    return Fraction(Decimal(s))


def parse_weight(raw, unit, decimal_comma):
    """raw may carry its own unit suffix, which wins."""
    raw = raw.strip()
    m = re.match(r"^(.*?)\s*(kg|g|lb|oz)$", raw, re.I)
    if m:
        raw, unit = m.group(1), m.group(2).lower()
    return parse_num(raw, decimal_comma) * KG[unit]


def parse_date(v, form):
    v = v.strip()
    form = (form or "").strip()
    m = re.match(r"^(\d{4})-(\d{2})-(\d{2})", v)
    if m:
        return date(*map(int, m.groups()))
    m = re.match(r"^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?\s+(\d{4})$", v)
    if m:
        return date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    f = form.lower()
    if f == "serial" or re.fullmatch(r"\d{5}(\.\d+)?", v):
        return date(1899, 12, 30) + timedelta(days=int(float(v)))
    if re.fullmatch(r"\d{8}", v):
        return date(int(v[:4]), int(v[4:6]), int(v[6:]))
    if re.fullmatch(r"\d{7}", v):
        return date(int(v[:4]), 1, 1) + timedelta(days=int(v[4:]) - 1)
    p = [int(x) for x in re.split(r"\D+", v) if x]
    if f in ("mm/dd/yyyy", "mdy"):
        return date(p[2], p[0], p[1])
    if f in ("ymd", "iso", "yyyy-mm-dd"):
        return date(*p[:3])
    return date(p[2], p[1], p[0])  # DMY, DD/MM/YYYY, DD.MM.YYYY


def parse_time(v, form=None):
    """Return the UTC date of a ship date or ship time."""
    v = v.strip()
    if re.match(r"^\d{4}-\d{2}-\d{2}[T ]\d", v):
        dt = datetime.fromisoformat(v.replace(" ", "T", 1))
        if dt.tzinfo is not None:
            dt = dt.astimezone(timezone.utc)
        return dt.date()
    return parse_date(v, form)


def split_quoted_lines(text):
    """Yield (kind, payload): comment lines or logical records (quote-aware)."""
    buf = None
    for line in text.split("\n"):
        line = line.rstrip("\r") if buf is None else line
        if buf is None:
            if line.startswith("#"):
                yield "comment", line
                continue
            if not line.strip():
                continue
            buf = line
        else:
            buf += "\n" + line.rstrip("\r")
        if buf.count('"') % 2 == 0:
            yield "row", buf
            buf = None
    if buf is not None:
        yield "row", buf


def split_csv(row):
    out, cur, i, q = [], [], 0, False
    while i < len(row):
        c = row[i]
        if q:
            if c == '"':
                if row[i + 1:i + 2] == '"':
                    cur.append('"')
                    i += 1
                else:
                    q = False
            else:
                cur.append(c)
        elif c == '"':
            q = True
        elif c == ",":
            out.append("".join(cur))
            cur = []
        else:
            cur.append(c)
        i += 1
    out.append("".join(cur))
    return out


def parse_delimited(depot, text):
    delim = DELIM[depot]
    cols = COLUMNS[depot]
    seq = None
    unit = BASE_UNIT[depot]
    dform = BASE_DATE[depot]
    dcomma = depot == "west"
    header = None
    recs = []
    for kind, payload in split_quoted_lines(text):
        if kind == "comment":
            m = re.match(r"^#\s*seq\s*[:=]\s*(\d+)", payload, re.I) or \
                re.match(r"^#\s*\w+ export seq=(\d+)", payload, re.I)
            if m and seq is None:
                seq = int(m.group(1))
                continue
            m = re.match(r"^#\s*([^:]+?)\s*:\s*(.*?)\s*$", payload)
            if m:
                name, val = m.group(1).lower(), m.group(2)
                if name in ("unit", "weight unit"):
                    u = val.split()[0].lower() if val.split() else ""
                    if u in KG:
                        unit = u
                    if name == "weight unit":
                        dcomma = "decimal comma" in val.lower()
                elif name in ("dates", "date format", "date"):
                    dform = val
            continue
        row = split_csv(payload) if delim == "," else payload.split(delim)
        low = [c.strip().lower() for c in row]
        if all(c in cols for c in low if c) and any(low) and len(set(low)) == len(low) \
                and sum(1 for c in low if c in cols) >= 2:
            header = low
            continue
        if header is None:
            continue
        ix = {c: i for i, c in enumerate(header)}
        wcol = WEIGHT_COL[depot]
        row_unit = None
        if len(row) == len(header) + 1 and wcol in ix:
            w = ix[wcol]
            if row[w + 1].strip().lower() in KG:
                row_unit = row[w + 1].strip().lower()
                row = row[:w + 1] + row[w + 2:]
        if len(row) < len(header):
            row = row + [""] * (len(header) - len(row))

        def get(c):
            return row[ix[c]].strip() if c in ix and ix[c] < len(row) else ""
        num = id_num(get(ID_COL[depot]))
        if num is None:
            continue
        typ = norm_type(get(TYPE_COL[depot]))
        if typ == "void":
            recs.append((num, typ, None))
            continue
        u = unit
        if row_unit:
            u = row_unit
        m = re.search(r"_(kg|g|lb|oz)$", wcol)
        if m:
            u = m.group(1)
        st = get(STATUS_COL[depot])
        st = HARBOR_STATES.get(st.upper(), st) if depot == "harbor" else st
        try:
            kg = parse_weight(get(wcol), u, dcomma)
            d = parse_time(get(DATE_COL[depot]), dform)
        except (ValueError, ArithmeticError, IndexError, KeyError):
            if typ == "new":
                continue
            kg, d = None, None
        recs.append((num, typ, (kg, d, norm_status(st))))
    return seq, recs


def parse_fixed(text):
    layouts = {
        "FW1": (42, {"type": (9, 10), "date": (10, 17), "w": (17, 25), "s": (25, 26),
                     "id": (0, 9)}, "yd", Fraction(1, 1000)),
        "FW2": (43, {"type": (0, 1), "id": (1, 10), "date": (10, 18), "w": (18, 26),
                     "s": (26, 27)}, "ymd", Fraction(1, 100)),
        "FW3": (41, {"id": (0, 9), "date": (9, 16), "type": (16, 17), "w": (17, 24),
                     "s": (24, 25)}, "yd", KG["lb"] / 10),
    }
    by_len = {v[0]: k for k, v in layouts.items()}
    seq = None
    cur = None
    recs = []
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if "\x0c" in line or not line.strip():
            continue
        if line.startswith("#"):
            m = re.match(r"^#LAYOUT\s+(\w+)", line)
            if m:
                cur = m.group(1)
            m = re.match(r"^#SEQ\s+(\d+)", line)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        name = by_len.get(len(line), cur)
        if name not in layouts:
            continue
        _, f, dform, scale = layouts[name]
        g = lambda k: line[f[k][0]:f[k][1]]
        num = id_num(g("id"))
        if num is None:
            continue
        typ = norm_type(g("type"))
        if typ == "void":
            recs.append((num, typ, None))
            continue
        try:
            ds = g("date")
            if dform == "yd":
                d = date(int(ds[:4]), 1, 1) + timedelta(days=int(ds[4:]) - 1)
            else:
                d = date(int(ds[:4]), int(ds[4:6]), int(ds[6:]))
            kg = int(g("w")) * scale
            if name == "FW1":
                kg = int(g("w")) * KG["g"]
        except ValueError:
            continue
        recs.append((num, typ, (kg, d, FW_CODES.get(g("s").strip(), g("s").strip().lower()))))
    return seq, recs


def parse_xml(b):
    root = ET.fromstring(b)
    seq = int(root.get("seq")) if (root.get("seq") or "").isdigit() else None
    runit = (root.get("weight-unit") or BASE_UNIT["central"]).strip().lower()
    recs = []
    for sh in root.iter("shipment"):
        num = id_num(sh.get("id"))
        if num is None:
            continue
        typ = norm_type(sh.get("type"))
        if typ == "void":
            recs.append((num, typ, None))
            continue
        try:
            w = sh.find("weight")
            u = (w.get("unit") or sh.get("weight-unit") or runit).strip().lower()
            kg = parse_weight(w.text or "", u, False)
            sv = sh.get("shipped")
            if sv is None:
                sv = sh.findtext("shipped")
            d = parse_time(sv)
            st = norm_status(sh.findtext("status"))
        except (ValueError, ArithmeticError, AttributeError, KeyError, TypeError):
            continue
        recs.append((num, typ, (kg, d, st)))
    return seq, recs


def parse_json(text):
    seq = None
    recs = []
    for line in text.split("\n"):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        try:
            val = json.loads(line)
        except ValueError:
            continue
        for o in (val if isinstance(val, list) else [val]):
            if not isinstance(o, dict):
                continue
            if "meta" in o and isinstance(o["meta"], dict):
                if seq is None and isinstance(o["meta"].get("seq"), int):
                    seq = o["meta"]["seq"]
                continue
            num = id_num(str(o.get("id", "")))
            if num is None:
                continue
            typ = norm_type(o.get("kind"))
            if typ == "void":
                recs.append((num, typ, None))
                continue
            try:
                kg = None
                for k, v in o.items():
                    m = re.fullmatch(r"weight_(kg|g|lb|oz)", k.lower())
                    if m:
                        kg = parse_weight(str(v), m.group(1), False)
                if kg is None and "weight" in o:
                    kg = parse_weight(str(o["weight"]), str(o.get("unit", "kg")).lower(), False)
                d = parse_time(str(o["shipped_at"]))
                recs.append((num, typ, (kg, d, norm_status(o.get("status")))))
            except (ValueError, ArithmeticError, KeyError, TypeError):
                continue
    return seq, recs


def parse_file(depot, path):
    b = read_bytes(path)
    stripped = b.lstrip(b"\xef\xbb\xbf \t\r\n")
    if depot == "central" or stripped[:5] == b"<?xml" or stripped[:7] == b"<export":
        return parse_xml(b)
    text = decode(b)
    if depot == "south":
        return parse_fixed(text)
    if depot == "north":
        return parse_json(text)
    if depot in DELIM:
        return parse_delimited(depot, text)
    return None, []


def main(data_dir, out_file):
    files = sorted(f for f in os.listdir(data_dir)
                   if os.path.isfile(os.path.join(data_dir, f)))
    depots = {}
    exports = {}
    for i, f in enumerate(files):
        depot = f.split("-")[0]
        depots.setdefault(depot, [])
        try:
            seq, recs = parse_file(depot, os.path.join(data_dir, f))
        except Exception as e:  # keep going on a damaged file
            print(f"warning: {f}: {e}", file=sys.stderr)
            continue
        exports.setdefault(depot, []).append((seq if seq is not None else -1, i, recs))

    corrections = resends = 0
    current = {}
    for depot, exps in exports.items():
        cur = {}
        for _, _, recs in sorted(exps, key=lambda e: (e[0], e[1])):
            for num, typ, data in recs:
                if typ == "new":
                    if num in cur:
                        resends += 1
                    else:
                        cur[num] = data
                elif typ == "correction":
                    corrections += 1
                    cur[num] = data
                else:
                    corrections += 1
                    cur.pop(num, None)
        current[depot] = cur

    def rank(d):
        return HANDOVER_ORDER.index(d) if d in HANDOVER_ORDER else len(HANDOVER_ORDER)
    owners = {}
    for depot in sorted(current, key=lambda d: (rank(d), d)):
        for num in current[depot]:
            owners.setdefault(num, []).append(depot)
    handovers = sum(1 for o in owners.values() if len(o) > 1)

    dep = {d: [0, Fraction(0)] for d in depots}
    mon = {}
    for num, o in owners.items():
        kg, d, st = current[o[0]][num]
        if st not in COUNTED or kg is None or d is None:
            continue
        dep[o[0]][0] += 1
        dep[o[0]][1] += kg
        m = mon.setdefault(f"{d.year:04d}-{d.month:02d}", [0, Fraction(0)])
        m[0] += 1
        m[1] += kg

    def rnd(fr):
        return float((Decimal(fr.numerator) / Decimal(fr.denominator) if False else
                      (Decimal(fr.numerator) * 10**30 // Decimal(fr.denominator))
                      ).scaleb(-30).quantize(Decimal("0.01"), ROUND_HALF_UP)) if False else \
            float(Decimal(round_half_up(fr)))

    def round_half_up(fr):
        n = (fr * 100 * 2 + 1) // 2  # floor(x*100 + 1/2), values are non-negative
        return Decimal(n.numerator // n.denominator) / 100

    out = {
        "depots": {d: {"shipments": v[0], "total_kg": rnd(v[1])} for d, v in sorted(dep.items())},
        "months": {k: {"shipments": v[0], "total_kg": rnd(v[1])} for k, v in sorted(mon.items())},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as f:
        json.dump(out, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
